import React from "react";
import { Box, Text } from "ink";
import { theme } from "../theme.ts";

/** Minimal, stable markdown renderer for transcript messages. */
export function Markdown({ text }: { text: string }): React.ReactElement {
  const lines = text.split("\n");
  const blocks: React.ReactElement[] = [];
  let codeBuffer: string[] | null = null;
  let codeLang = "";

  lines.forEach((line, i) => {
    const fence = line.match(/^\s*```(\w*)\s*$/);
    if (fence) {
      if (codeBuffer === null) {
        codeBuffer = [];
        codeLang = fence[1];
      } else {
        blocks.push(
          <Box key={`code-${i}`} flexDirection="column" marginLeft={1}>
            {codeLang ? (
              <Text color={theme.faint}>┌ {codeLang}</Text>
            ) : (
              <Text color={theme.faint}>┌</Text>
            )}
            {codeBuffer.map((cl, j) => (
              <Text key={j}>
                <Text color={theme.faint}>│ </Text>
                <Text color={theme.amber}>{cl || " "}</Text>
              </Text>
            ))}
            <Text color={theme.faint}>└</Text>
          </Box>,
        );
        codeBuffer = null;
        codeLang = "";
      }
      return;
    }
    if (codeBuffer !== null) {
      codeBuffer.push(line);
      return;
    }
    const header = line.match(/^(#{1,4})\s+(.*)$/);
    if (header) {
      blocks.push(
        <Text key={i} bold color={theme.orange}>
          {header[2]}
        </Text>,
      );
      return;
    }
    const bullet = line.match(/^(\s*)[-*]\s+(.*)$/);
    if (bullet) {
      blocks.push(
        <Text key={i}>
          {bullet[1]}
          <Text color={theme.orange}>• </Text>
          {inline(bullet[2])}
        </Text>,
      );
      return;
    }
    const numbered = line.match(/^(\s*)(\d+)\.\s+(.*)$/);
    if (numbered) {
      blocks.push(
        <Text key={i}>
          {numbered[1]}
          <Text color={theme.orange}>{numbered[2]}. </Text>
          {inline(numbered[3])}
        </Text>,
      );
      return;
    }
    blocks.push(<Text key={i}>{line.trim() === "" ? " " : inline(line)}</Text>);
  });

  // Unterminated fence — flush as code anyway.
  if (codeBuffer !== null) {
    const buffered = codeBuffer as string[];
    blocks.push(
      <Box key="code-tail" flexDirection="column" marginLeft={1}>
        {buffered.map((cl, j) => (
          <Text key={j}>
            <Text color={theme.faint}>│ </Text>
            <Text color={theme.amber}>{cl || " "}</Text>
          </Text>
        ))}
      </Box>,
    );
  }

  return <Box flexDirection="column">{blocks}</Box>;
}

function inline(text: string): React.ReactNode[] {
  const nodes: React.ReactNode[] = [];
  const re = /(\*\*[^*]+\*\*|`[^`]+`|\*[^*\s][^*]*\*)/g;
  let last = 0;
  let key = 0;
  for (const m of text.matchAll(re)) {
    if (m.index! > last) nodes.push(<Text key={key++}>{text.slice(last, m.index)}</Text>);
    const tok = m[0];
    if (tok.startsWith("**")) {
      nodes.push(
        <Text key={key++} bold color={theme.ink}>
          {tok.slice(2, -2)}
        </Text>,
      );
    } else if (tok.startsWith("`")) {
      nodes.push(
        <Text key={key++} color={theme.amber}>
          {tok.slice(1, -1)}
        </Text>,
      );
    } else {
      nodes.push(
        <Text key={key++} italic>
          {tok.slice(1, -1)}
        </Text>,
      );
    }
    last = m.index! + tok.length;
  }
  if (last < text.length) nodes.push(<Text key={key++}>{text.slice(last)}</Text>);
  return nodes;
}
